const data = $input.first().json;
const creneaux = data.creneaux || [];

function fmtDate(s) {
  const d = new Date(s);
  if(isNaN(d)) return s;
  return d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit',year:'numeric'});
}
function getDayNum(s){return new Date(s).getDay();}
function getSemaineDates(s){
  const base=new Date(s),dates={};
  for(let i=0;i<5;i++){const d=new Date(base);d.setDate(base.getDate()+i);dates[i+1]=fmtDate(d.toISOString().split('T')[0]);}
  return dates;
}

const dates=getSemaineDates(data.semaineDu);
const HORAIRES=[{d:'08:00',l:'08H-10H'},{d:'10:00',l:'10H-12H'},{d:'13:00',l:'13H-15H'},{d:'15:00',l:'15H-17H'}];
const JOURS=['Lundi','Mardi','Mercredi','Jeudi','Vendredi'];

function getCreneau(day,heure){
  return creneaux.find(c=>getDayNum(c.jour)===day && (c.heureDebut||'').substring(0,5)===heure);
}
function cell(day,heure){
  const c=getCreneau(day,heure);
  if(!c) return `<td style="border:1px solid #000;height:90px;"></td>`;
  return `<td style="border:1px solid #000;padding:6px;height:90px;vertical-align:top;">
    <span style="background:#FFFF00;font-weight:bold;font-size:11px;display:block;padding:1px 3px;">${c.module||c.matiere||''}</span>
    <span style="background:#FFFF00;font-size:11px;display:block;padding:1px 3px;">${c.salle?'Salle '+c.salle:''}</span>
    <span style="font-size:11px;display:block;">${c.professeur||''}</span>
  </td>`;
}

const headerCells=JOURS.map((j,i)=>`<th style="border:1px solid #000;padding:5px;font-size:11px;text-align:left;">${j}<br><span style="font-weight:normal;">${dates[i+1]||''}</span></th>`).join('');

const lignes=HORAIRES.map((h,i)=>{
  const sep=i===2?`<tr><td colspan="6" style="background:#4472C4;height:14px;border:none;"></td></tr>`:'';
  return `${sep}<tr><td style="border:1px solid #000;color:#C00000;font-weight:bold;font-size:11px;text-align:center;vertical-align:middle;width:65px;">${h.l}</td>${[1,2,3,4,5].map(d=>cell(d,h.d)).join('')}</tr>`;
}).join('');

const iaBanner = data.iaActive && data.suggestions
  ? `<div style="background:#EEF2FF;border-left:4px solid #4338CA;padding:10px 14px;margin-bottom:16px;border-radius:0 6px 6px 0;"><strong style="color:#4338CA;font-size:12px;">🤖 Optimisé par Claude IA (Anthropic)</strong><p style="color:#374151;font-size:11px;margin:4px 0 0;">${data.suggestions}</p></div>` : '';

const html=`<!DOCTYPE html><html><head><meta charset='utf-8'><style>body{font-family:Arial,sans-serif;padding:28px;background:#fff;color:#000;}table{border-collapse:collapse;width:100%;}</style></head><body>
<div style="display:flex;align-items:flex-start;margin-bottom:20px;"><div style="border:2px solid #1E3A5F;padding:8px 12px;border-radius:6px;"><div style="font-weight:900;font-size:12px;color:#1E3A5F;line-height:1.5;">Institut<br>Supérieur<br><span style="text-decoration:underline;">du Digital®</span></div></div></div>
${iaBanner}
<div style="text-align:center;font-weight:bold;font-size:15px;text-decoration:underline;text-transform:uppercase;margin-bottom:5px;">EMPLOI DU TEMPS (${fmtDate(data.semaineDu)} - ${fmtDate(data.semaineAu)})</div>
<div style="text-align:center;font-size:13px;text-decoration:underline;text-transform:uppercase;margin-bottom:18px;">${data.niveau} : ${data.filiere}</div>
<table><thead><tr><th style="border:1px solid #000;padding:5px;font-size:11px;width:65px;">Heures</th>${headerCells}</tr></thead><tbody>${lignes}</tbody></table>
<p style="color:#C00000;font-style:italic;font-weight:bold;text-decoration:underline;margin-top:18px;font-size:12px;">NB : L'emploi du temps n'est pas définitif il peut toujours subir des modifications.</p>
</body></html>`;

return [{json:{...data,htmlEmail:html}}];
